CREATE TABLE IF NOT EXISTS "customers" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int UNIQUE,
  "customer_code" varchar(30) UNIQUE,
  "full_name" varchar(255) NOT NULL,
  "birthday" date,
  "phone_number" varchar(20),
  "email" varchar(255),
  "created_at" timestamp
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'fk_customers_users'
  ) THEN
    ALTER TABLE "customers" ADD CONSTRAINT fk_customers_users FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
  END IF;
END $$;
